"use strict";

// The Taiwan route solver and mileage statistics run on their OWN pair of
// datasets (rail-sections-tw / stations-tw), generated by
// scripts/railway/build-taiwan-rail-package.py in the same official pass that builds
// the display package. These tests pin the contract that makes one solver
// serve both countries: the neutral property schema, station identity that
// matches what a Taiwanese train's stops actually record, geometry shared with
// the drawn map, and a code space the statistics can classify.

const assert = require("node:assert/strict");
const fs = require("node:fs");
const path = require("node:path");
const test = require("node:test");

const SECTIONS_PATH = path.join(__dirname, "../data/rail-sections-tw.json");
const STATIONS_PATH = path.join(__dirname, "../data/stations-tw.json");
const JP_STATIONS_PATH = path.join(__dirname, "../data/stations.json");
const TW_STORE_PATH = path.join(__dirname, "../data/train-store-tw.json");
const PACKAGE_PATH = path.join(__dirname, "../public/rail/tw-2025.json");

const readJson = (file) => JSON.parse(fs.readFileSync(file, "utf8"));

test("Taiwan solver datasets answer the shared country-neutral schema", () => {
  const sections = readJson(SECTIONS_PATH);
  const stations = readJson(STATIONS_PATH);

  assert.equal(sections.type, "FeatureCollection");
  assert.equal(stations.type, "FeatureCollection");
  // One section per station interval, one station feature per line membership
  // — the same shape the package audit pins.
  // One row per drawn interval / station, so these follow the package: the
  // 中和新蘆線 collapse (scripts/railway/collapse-branch-services.mjs) stopped the
  // 蘆洲 branch repeating the twelve trunk stations it shares with 迴龍.
  assert.equal(sections.features.length, 548);
  assert.equal(stations.features.length, 586);

  for (const feature of sections.features) {
    const p = feature.properties;
    assert.equal(feature.geometry.type, "LineString");
    assert.ok(feature.geometry.coordinates.length >= 2);
    // Neutral names only: writing Japan's N02_* keys onto Taiwanese data would
    // make the schema a lie even though every reader accepts both.
    assert.ok(p.line_name, "section carries a line name");
    assert.ok(p.operator, "section carries an operator");
    assert.match(p.institution_type_code, /^[1-5]$/);
    assert.match(p.railway_class_code, /^(11|12|21|31)$/);
    assert.ok(!("N02_003" in p), "must not borrow the N02 spelling");
  }

  for (const feature of stations.features) {
    const p = feature.properties;
    assert.ok(p.station_name, "station carries a name");
    assert.ok(p.n02_station_code, "station carries an official code");
    assert.ok(p.n02_group_code, "station carries its transfer group");
    assert.equal(p.display_point.length, 2);
    // The marker coordinate IS the first vertex of the station's own routed
    // geometry, so the solver's graph node and the drawn dot cannot drift.
    assert.deepEqual(p.display_point, feature.geometry.coordinates[0]);
  }
});

test("every Taiwan stop resolves against the Taiwan station dataset", () => {
  const stations = readJson(STATIONS_PATH);
  const codes = new Set(
    stations.features.map((f) => f.properties.n02_station_code),
  );
  const names = new Set(stations.features.map((f) => f.properties.station_name));
  const store = readJson(TW_STORE_PATH);

  let checked = 0;
  for (const train of store.trains) {
    for (const stop of train.stops || []) {
      checked += 1;
      if (stop.n02_station_code)
        assert.ok(
          codes.has(stop.n02_station_code),
          `${train.number}: unknown station code ${stop.n02_station_code}`,
        );
      if (stop.name)
        assert.ok(
          names.has(stop.name),
          `${train.number}: unknown station name ${stop.name}`,
        );
    }
  }
  assert.ok(checked > 0, "the Taiwan store has stops to check");
});

test("Taiwan station codes are TDX StationUIDs and never collide with Japan", () => {
  const stations = readJson(STATIONS_PATH);
  const twCodes = new Set(
    stations.features.map((f) => f.properties.n02_station_code),
  );
  // stationCodeSystem() in app-stations.js distinguishes the two systems by
  // shape: six digits is N02, SYSTEM-ID is TDX. Any overlap would let a stop
  // resolve in the wrong country.
  for (const code of twCodes) {
    assert.match(code, /^[A-Z][A-Z0-9]*-[A-Za-z0-9]+(?:-[A-Za-z0-9]+)*$/);
    assert.ok(!/^\d{6}$/.test(code));
  }

  const jpStations = readJson(JP_STATIONS_PATH);
  const jpCodes = new Set(
    jpStations.features.map((f) => f.properties.N02_005c).filter(Boolean),
  );
  for (const code of twCodes)
    assert.ok(!jpCodes.has(code), `code ${code} exists in both countries`);
});

test("Taiwan sections classify into every statistics bucket", () => {
  const sections = readJson(SECTIONS_PATH);
  // Mirrors classifyTwSectionMask in app-stats.js: high speed, 臺鐵, 捷運,
  // 輕軌, and the 阿里山林業鐵路 must each be reachable, or a coverage row
  // would silently render an empty category.
  const bucketOf = (p) => {
    if (p.institution_type_code === "1") return "hsr";
    if (p.railway_class_code === "21") return "lrt";
    if (p.railway_class_code === "31") return "forest";
    if (p.institution_type_code === "3") return "metro";
    return "tra";
  };
  const seen = new Set(sections.features.map((f) => bucketOf(f.properties)));
  for (const bucket of ["hsr", "tra", "metro", "lrt", "forest"])
    assert.ok(seen.has(bucket), `no section classified as ${bucket}`);
});

test("Taiwan section geometry matches the drawn rail package", () => {
  const sections = readJson(SECTIONS_PATH);
  const compact = readJson(PACKAGE_PATH);

  // Both outputs come from the same groomed station intervals.  Compare every
  // complete ordered interval, not just the global vertex set: a shortest-path
  // shortcut through an Alishan switchback can use only legitimate package
  // vertices while still dropping/reordering the intentional reversal tail.
  // Sections carry (line_name, operator), and a trunk and its own branch share
  // both — 中和新蘆線 runs to 迴龍 with 蘆洲 hanging off 大橋頭, and both rows
  // carry the line's name so the renderer draws their shared track once
  // (scripts/railway/collapse-branch-services.mjs). The file is written line by line
  // in package order, so consume each line's own run from the front of its
  // group rather than re-filtering and getting both.
  const queues = new Map();
  for (const feature of sections.features) {
    const key = `${feature.properties.line_name}\u0000${feature.properties.operator}`;
    const queue = queues.get(key) || [];
    queue.push(feature);
    queues.set(key, queue);
  }
  let checked = 0;
  for (const line of compact.lines) {
    let previous = null;
    const queue = queues.get(`${line.name}\u0000${line.operator}`) || [];
    const lineSections = queue.splice(0, line.segments.length);
    assert.equal(
      lineSections.length,
      line.segments.length,
      `${line.id} solver/display interval count`,
    );
    for (let index = 0; index < line.segments.length; index += 1) {
      const [, shared, coords] = line.segments[index];
      const full = shared && previous ? [previous, ...coords] : coords;
      assert.deepEqual(
        lineSections[index].geometry.coordinates,
        full,
        `${line.id} interval ${index} differs from the drawn package`,
      );
      previous = full[full.length - 1];
      checked += full.length;
    }
  }
  assert.ok(checked > 10000, "compared the full section vertex set");
});
